-- AD34 CHECK (B13 T4a manual company exception with a second reviewer): every row must be true
SELECT 'the six bind.* ledger kinds exist, bind.refused is high' AS rule, (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('bind.proposed', 'bind.approved', 'bind.denied', 'bind.withdrawn', 'bind.expired', 'bind.refused')) = 6 AND EXISTS (SELECT 1 FROM desk.fadm_ledger_kind WHERE kind = 'bind.refused' AND severity = 'high') AS ok
UNION ALL SELECT 'the proposal table is forced RLS, closed to PUBLIC and to desk_app, with a deny-all policy',
  (SELECT relforcerowsecurity FROM pg_class WHERE oid = 'desk.fadm_bind_proposal'::regclass) AND NOT has_table_privilege('public', 'desk.fadm_bind_proposal', 'SELECT') AND NOT has_table_privilege('desk_app', 'desk.fadm_bind_proposal', 'SELECT') AND NOT has_table_privilege('desk_app', 'desk.fadm_bind_proposal', 'INSERT')
  AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'desk' AND tablename = 'fadm_bind_proposal' AND policyname = 'p_bind_proposal_none')
UNION ALL SELECT 'one open proposal per case is a partial unique index', EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'desk' AND indexname = 'fadm_bind_proposal_one_open' AND indexdef ILIKE '%UNIQUE%' AND indexdef ILIKE '%pending%')
UNION ALL SELECT 'the two-people rule is a table CHECK (decider <> proposer) and the 24 hour window is a CHECK',
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_bind_proposal'::regclass AND conname = 'fadm_bind_proposal_two_people' AND pg_get_constraintdef(oid) ILIKE '%decided_by%proposer%')
  AND EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_bind_proposal'::regclass AND conname = 'fadm_bind_proposal_window' AND pg_get_constraintdef(oid) ILIKE '%24:00:00%')
UNION ALL SELECT 'the guard trigger blocks UPDATE of a decided row, DELETE and TRUNCATE', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'desk.fadm_bind_proposal'::regclass AND tgname IN ('fadm_bind_proposal_guard', 'fadm_bind_proposal_guard_t') AND NOT tgisinternal) = 2
UNION ALL SELECT 'every door is SECURITY DEFINER with a fixed search_path and a statement timeout, commented; desk_app may run the five doors, PUBLIC may not run any',
  (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.proname IN ('fadm_bind_propose', 'fadm_bind_decide', 'fadm_bind_withdraw', 'fadm_bind_pending', 'fadm_bind_sweep', 'fadm_bind_may') AND p.prosecdef AND p.proconfig::text LIKE '%search_path=pg_catalog, desk%' AND obj_description(p.oid, 'pg_proc') IS NOT NULL OR p.proname = 'fadm_bind_may') >= 5
  AND has_function_privilege('desk_app', 'desk.fadm_bind_propose(uuid,text,uuid,text,text)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_bind_decide(uuid,uuid,boolean)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_bind_withdraw(uuid,uuid)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_bind_pending(uuid)', 'EXECUTE')
  AND NOT has_function_privilege('public', 'desk.fadm_bind_propose(uuid,text,uuid,text,text)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.fadm_bind_decide(uuid,uuid,boolean)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.fadm_bind_may(uuid)', 'EXECUTE')
UNION ALL SELECT 'approval goes through the ONE writer: AD30 fadm_case_bind is still the only function that inserts a binding and stays closed to PUBLIC',
  NOT has_function_privilege('public', 'desk.fadm_case_bind(text,uuid,text,uuid,uuid,jsonb)', 'EXECUTE') AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.prosrc ILIKE '%INSERT INTO desk.fadm_case_binding%') = 1
UNION ALL SELECT 'every manual binding (FACT over all rows so far) has a proposal id as evidence and two different people', NOT EXISTS (SELECT 1 FROM desk.fadm_case_binding WHERE source = 'manual_exception' AND (evidence ->> 'proposal' IS NULL OR actor IS NULL OR reviewer IS NULL OR actor = reviewer))
UNION ALL SELECT 'no bind.* ledger line holds a key outside the closed set (FACT)', NOT EXISTS (SELECT 1 FROM desk.fadm_ledger l, jsonb_object_keys(l.detail) k WHERE l.kind LIKE 'bind.%' AND k NOT IN ('proposal', 'case', 'tenant', 'reason', 'why', 'step'))
UNION ALL SELECT 'no approved row can be later than its 24 hours (table CHECK, worker or not)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.fadm_bind_proposal'::regclass AND conname = 'fadm_bind_proposal_no_late_approval' AND pg_get_constraintdef(oid) ILIKE '%expires_at%')
UNION ALL SELECT 'decide and withdraw take the row lock (FOR UPDATE) and the advisory lock, and decide expires an old proposal itself',
  (SELECT bool_and(p.prosrc ILIKE '%FOR UPDATE%' AND p.prosrc ILIKE '%pg_advisory_xact_lock%') FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.proname IN ('fadm_bind_decide', 'fadm_bind_withdraw'))
  AND (SELECT p.prosrc ILIKE '%expires_at <= now()%' FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.proname = 'fadm_bind_decide')
UNION ALL SELECT 'no door of this phase has public in its search_path and every one pins it (SECURITY DEFINER hygiene)',
  NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.proname IN ('fadm_bind_propose', 'fadm_bind_decide', 'fadm_bind_withdraw', 'fadm_bind_pending', 'fadm_bind_sweep', 'fadm_bind_may') AND (p.proconfig IS NULL OR p.proconfig::text NOT LIKE '%search_path=pg_catalog, desk%' OR p.proconfig::text LIKE '%public%'))
UNION ALL SELECT 'the app role is not a superuser, has no BYPASSRLS, cannot create objects in schema desk or public (untrusted schema protection)',
  EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'desk_app' AND NOT rolsuper AND NOT rolbypassrls) AND NOT has_schema_privilege('desk_app', 'desk', 'CREATE') AND NOT has_schema_privilege('desk_app', 'public', 'CREATE')
UNION ALL SELECT 'T4g: the six doors are owned by desk_bind_owner (NOLOGIN, no superuser, no BYPASSRLS), not by the installer', (SELECT count(*) FROM pg_proc p JOIN pg_roles r ON r.oid = p.proowner WHERE p.pronamespace = 'desk'::regnamespace AND p.proname IN ('fadm_bind_propose','fadm_bind_decide','fadm_bind_withdraw','fadm_bind_pending','fadm_bind_sweep','fadm_bind_may') AND r.rolname = 'desk_bind_owner' AND NOT r.rolcanlogin AND NOT r.rolsuper AND NOT r.rolbypassrls) = 6
UNION ALL SELECT 'the ledger chain verifies', desk.fadm_ledger_verify()
UNION ALL SELECT 'earlier phases are untouched (AD30 reader still answers, consent door still closed to PUBLIC)', desk.fadm_case_tenant('no-such-case') IS NULL AND NOT has_function_privilege('public', 'desk.fadm_consent_request(uuid,text,text,text)', 'EXECUTE');
